import openpyxl, re
from collections import Counter
wb = openpyxl.load_workbook('134_134_darron_c_giron_002_1_1_1.pst.143_embedded_hardcodes_6139_input.xlsx')
pat = Counter()
for ws in wb.worksheets:
    for row in ws.iter_rows():
        for c in row:
            if c.value is not None and isinstance(c.value, str) and c.value.startswith('='):
                # normalize by replacing cell refs
                norm = re.sub(r'[A-Z]+[0-9]+', 'C', c.value)
                norm = re.sub(r'[0-9]+(?:\.[0-9]+)?', 'N', norm)
                pat[norm] += 1
for k,v in pat.most_common():
    print(v, k)
"

